"""Convert a sequence of whitespace separated tokens
    each containing no more than 8 0's and 1's to a list of bytes.
    Raise Exception if illegal.
    """
def binEntryBytes(binStr: Any) -> object {
    `bytes = [];
    for (i, token) in enumerate(binStr.split()) {
        if (len(token) > 8) {
            raise Exception("Token {} is more than 8 bits: {}".format((i + 1), token));
        }
        `bytes.append(int(token, 2));
    }
    return `bytes;
}

"""
    Reverses ``encode_topic_name``.

    :param encoded: the encoded SNS topic name
    :return: the decoded channel name
    """
def decode_topic_name(encoded: str) -> str {
    decoded = encoded;
    decoded = decoded.replace("_WCD_", "*");
    decoded = decoded.replace("_FWS_", "/");
    decoded = decoded.replace("_DOT_", ".");
    decoded = decoded.replace("_COL_", ":");
    decoded = decoded.replace("_LT_", "<");
    decoded = decoded.replace("_GT_", ">");
    return decoded;
}

